import 'package:flutter/material.dart';
import '../state/app_state.dart';
class OrderItemAvailabilityNotice extends StatefulWidget {
 const OrderItemAvailabilityNotice({super.key,required this.order});
 final Map<String,dynamic> order;
 @override State<OrderItemAvailabilityNotice> createState()=>_NoticeState();
}
class _NoticeState extends State<OrderItemAvailabilityNotice>{
 bool busy=false;String? error;
 String money(dynamic value)=>'R\$ ${(double.tryParse(value.toString())??0).toStringAsFixed(2).replaceAll('.',',')}';
 Future<void> choose(dynamic item,String choice,{String? productId})async{
 final description=choice=='REFUND'?'Solicitar a devolução do valor pago pelo item? Créditos usados voltam ao seu saldo.':choice=='VOUCHER'?'Receber o valor deste item como crédito em produtos para a próxima compra?':'Confirmar a substituição pelo produto selecionado, sem custo adicional?';
 final confirmed=await showDialog<bool>(context:context,builder:(context)=>AlertDialog(title:const Text('Confirmar sua escolha'),content:Text(description),actions:[TextButton(onPressed:()=>Navigator.pop(context,false),child:const Text('Voltar')),FilledButton(onPressed:()=>Navigator.pop(context,true),child:const Text('Confirmar'))]));
 if(confirmed!=true||!mounted)return;setState((){busy=true;error=null;});
 try{await AppState.instance.resolveUnavailable(widget.order['id'].toString(),item['id'].toString(),choice,productId:productId);}catch(_){if(mounted)setState(()=>error='Não conseguimos confirmar agora. Atualize o pedido e tente novamente.');}finally{if(mounted)setState(()=>busy=false);}
 }
 @override Widget build(BuildContext context){
 final items=((widget.order['items'] as List?)??[]).where((i)=>i['availabilityStatus']!=null&&i['availabilityStatus']!='AVAILABLE').toList();
 if(items.isEmpty)return const SizedBox.shrink();
 return Padding(padding:const EdgeInsets.only(bottom:16),child:Container(padding:const EdgeInsets.all(20),decoration:BoxDecoration(color:const Color(0xFFFFF4F2),borderRadius:BorderRadius.circular(24),border:Border.all(color:const Color(0xFFF2B8AE))),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[const Icon(Icons.error_outline_rounded,color:Color(0xFFAB3329)),const SizedBox(width:10),Expanded(child:Text(widget.order['fulfillmentHold']==true?'Precisamos da sua escolha':'Atualização dos seus produtos',style:const TextStyle(fontWeight:FontWeight.w800,fontSize:19,color:Color(0xFF812C26))))]),const SizedBox(height:8),if(widget.order['fulfillmentHold']==true)const Text('Um produto ficou indisponível. Seu pedido está pausado enquanto resolvemos isso com você.',style:TextStyle(height:1.5)),...items.map((item){final status=item['availabilityStatus'];return Padding(padding:const EdgeInsets.only(top:16),child:Container(padding:const EdgeInsets.all(16),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(18)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${item['quantity']}× ${item['productName']}',style:const TextStyle(fontSize:16,fontWeight:FontWeight.w800)),const SizedBox(height:6),if(status=='AWAITING_CUSTOMER')...[Text(item['availabilityNote']??'Produto indisponível',style:const TextStyle(height:1.5)),const SizedBox(height:12),...((item['availabilityOptions'] as List?)??[]).map((p)=>Padding(padding:const EdgeInsets.only(bottom:8),child:OutlinedButton.icon(onPressed:busy?null:()=>choose(item,'REPLACEMENT',productId:p['id'].toString()),icon:const Icon(Icons.swap_horiz_rounded),label:Text('Trocar por ${p['name']}')))),Wrap(spacing:8,runSpacing:8,children:[FilledButton.icon(onPressed:busy?null:()=>choose(item,'REFUND'),icon:const Icon(Icons.undo_rounded),label:const Text('Reembolso')),OutlinedButton.icon(onPressed:busy?null:()=>choose(item,'VOUCHER'),icon:const Icon(Icons.confirmation_number_outlined),label:const Text('Voucher'))]),const SizedBox(height:8),Text('Valor do item: ${money(item['total'])}',style:const TextStyle(fontSize:12))],if(status=='REFUND_PROCESSING')Text(['failed','canceled'].contains(item['refundStatus'])?'A loja está verificando seu reembolso. Sua solicitação está registrada.':'Reembolso solicitado. A confirmação do pagamento está em processamento.',style:const TextStyle(height:1.5)),if(status=='REFUNDED')Text('Reembolso confirmado: ${money(item['refundAmount'])}. ${NumberText.credit(item['creditAmount'],money)}',style:const TextStyle(height:1.5)),if(status=='VOUCHERED')Text('${money(item['creditAmount'])} em crédito para produtos na próxima compra. Aplicação automática no checkout.',style:const TextStyle(height:1.5)),if(status=='REPLACED')Text('Substituição confirmada no lugar de ${item['originalProductName']}. Sem custo adicional.',style:const TextStyle(height:1.5))])));}),if(busy)const Padding(padding:EdgeInsets.only(top:12),child:LinearProgressIndicator()),if(error!=null)Padding(padding:const EdgeInsets.only(top:12),child:Text(error!,style:const TextStyle(color:Colors.red)))])));
 }
}
class NumberText{static String credit(dynamic value,String Function(dynamic) money)=>(double.tryParse(value.toString())??0)>0?'Créditos restaurados: ${money(value)}.':'';}
